use std::hash::{BuildHasher, Hash, Hasher};
use std::path::{Path, PathBuf};
use std::process::Command;

/// Inputs that can change either peer's executable behavior. Documentation and
/// other repository bookkeeping deliberately do not churn the wire build ID.
const BUILD_INPUTS: &[&str] = &["Cargo.toml", "Cargo.lock", "crates"];

fn run_git(manifest_dir: &Path, args: &[&str]) -> Option<Vec<u8>> {
    let output = Command::new("git")
        .args(args)
        .current_dir(manifest_dir)
        .output()
        .ok()?;
    output.status.success().then_some(output.stdout)
}

fn run_git_string(manifest_dir: &Path, args: &[&str]) -> Option<String> {
    run_git(manifest_dir, args).map(|bytes| String::from_utf8_lossy(&bytes).trim().to_string())
}

fn run_scoped_git(manifest_dir: &Path, args: &[&str]) -> Option<Vec<u8>> {
    let mut command = Command::new("git");
    command.args(args).arg("--");
    for input in BUILD_INPUTS {
        command.arg(format!(":(top){input}"));
    }
    let output = command.current_dir(manifest_dir).output().ok()?;
    output.status.success().then_some(output.stdout)
}

fn workspace_root(manifest_dir: &Path, emit_rerun: bool) -> PathBuf {
    if emit_rerun {
        if let Some(git_dir) = run_git_string(manifest_dir, &["rev-parse", "--absolute-git-dir"]) {
            println!("cargo:rerun-if-changed={git_dir}/HEAD");
            println!("cargo:rerun-if-changed={git_dir}/refs");
            println!("cargo:rerun-if-changed={git_dir}/index");
        }
    }
    let root = run_git_string(manifest_dir, &["rev-parse", "--show-toplevel"])
        .map(PathBuf::from)
        .or_else(|| {
            let candidate = manifest_dir.parent()?.parent()?;
            (candidate.join("Cargo.toml").is_file() && candidate.join("crates").is_dir())
                .then(|| candidate.to_path_buf())
        })
        .unwrap_or_else(|| manifest_dir.to_path_buf());
    if emit_rerun {
        for input in BUILD_INPUTS {
            let path = root.join(input);
            println!("cargo:rerun-if-changed={}", path.display());
        }
    }
    root
}

fn hash_untracked_contents(root: &Path, porcelain: &[u8], hasher: &mut impl Hasher) {
    for entry in porcelain.split(|byte| *byte == 0) {
        let Some(path_bytes) = entry.strip_prefix(b"?? ") else {
            continue;
        };
        path_bytes.hash(hasher);
        let path = root.join(String::from_utf8_lossy(path_bytes).as_ref());
        match std::fs::read(path) {
            Ok(contents) => contents.hash(hasher),
            Err(error) => {
                // A concurrent disappearance or unreadable build input must
                // not collapse onto the identity of a readable file.
                error.kind().hash(hasher);
            }
        }
    }
}

fn unknown_build_suffix() -> String {
    // Independent compilations must never false-match when their source
    // identity cannot be established. One built binary still matches itself.
    let nonce = std::collections::hash_map::RandomState::new()
        .build_hasher()
        .finish();
    format!("unknown.{nonce:016x}")
}

fn nonempty_env(value: Option<String>) -> Option<String> {
    value.and_then(|raw| {
        let trimmed = raw.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    })
}

fn parse_injected_sha(raw: &str) -> Result<String, String> {
    if raw.len() == 12
        && raw
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        Ok(raw.to_string())
    } else {
        Err(format!(
            "injected build SHA must be 12 lowercase hex digits, got {raw:?}"
        ))
    }
}

/// Prefer `BLIT_GIT_SHA`, then `BLIT_RELEASE_SHA`. Empty is unset.
/// Disagreeing non-empty values are an error, not a silent pick.
fn injected_sha(git: Option<String>, release: Option<String>) -> Result<Option<String>, String> {
    match (nonempty_env(git), nonempty_env(release)) {
        (Some(git_sha), Some(release_sha)) if git_sha != release_sha => Err(format!(
            "BLIT_GIT_SHA ({git_sha:?}) and BLIT_RELEASE_SHA ({release_sha:?}) disagree"
        )),
        (Some(sha), _) | (None, Some(sha)) => parse_injected_sha(&sha).map(Some),
        (None, None) => Ok(None),
    }
}

fn resolve_build_suffix(
    manifest_dir: &Path,
    emit_rerun: bool,
    git_env: Option<String>,
    release_env: Option<String>,
) -> Result<String, String> {
    if emit_rerun {
        println!("cargo:rerun-if-env-changed=BLIT_GIT_SHA");
        println!("cargo:rerun-if-env-changed=BLIT_RELEASE_SHA");
    }
    if let Some(sha) = injected_sha(git_env, release_env)? {
        return Ok(sha);
    }
    Ok(git_build_suffix_inner(manifest_dir, emit_rerun))
}

/// Git identity reported in the session handshake (informational
/// since D-2026-08-18-2; the gate is `CONTRACT_VERSION`).
///
/// Clean build inputs use the commit SHA. Dirty build inputs add a stable hash
/// of their scoped status, tracked diff, and untracked file contents. Every
/// watched workspace input is declared on every run, so separate Cargo target
/// profiles cannot retain different subsets of an older dirty tree.
fn git_build_suffix_inner(manifest_dir: &Path, emit_rerun: bool) -> String {
    let root = workspace_root(manifest_dir, emit_rerun);
    let Some(sha) = run_git_string(manifest_dir, &["rev-parse", "--short=12", "HEAD"])
        .filter(|sha| !sha.is_empty())
    else {
        return unknown_build_suffix();
    };

    let Some(porcelain) = run_scoped_git(
        manifest_dir,
        &["status", "--porcelain=v1", "-z", "--untracked-files=all"],
    ) else {
        return unknown_build_suffix();
    };
    if porcelain.is_empty() {
        return sha;
//! The same-build gate of the utility requests
//! (`docs/plan/UTILITY_VERBS_LOCAL_PARITY.md` AC-11, D-2026-11-20-4).
//!
//! A transfer session compares the two ends' contract versions at HELLO.
//! The utility requests are not sessions, so each carries the asker's
//! contract version and the daemon compares it before it reads or changes
//! anything ([`check`]). A daemon of an earlier contract does not serve
//! the request name at all: it answers "unimplemented", which the asker
//! reports as the same refusal ([`refusal`]).

use crate::transfer_session::CONTRACT_VERSION;

/// The daemon's half: refuse an asker of another contract, in the words a
/// transfer's refusal uses. `Ok` when the two speak the same one.
pub fn check(asker: u32) -> Result<(), tonic::Status> {
    if asker == CONTRACT_VERSION {
        return Ok(());
    }
    Err(tonic::Status::failed_precondition(mismatch(
        CONTRACT_VERSION,
        asker,
    )))
}

/// The refusal's words: this end's contract and the other's.
fn mismatch(daemon: u32, asker: u32) -> String {
    format!(
        "contract version mismatch (D-2026-08-18-2): daemon v{daemon} vs client v{asker}; \
         both must be the same blit release"
    )
}

/// The asker's half: what `status` from a utility request `verb` means.
/// A daemon that does not know the request at all is a daemon of another
/// contract; every other status is the daemon's own message.
pub fn refusal(verb: &str, status: tonic::Status) -> eyre::Report {
    if status.code() == tonic::Code::Unimplemented {
        return eyre::eyre!(
            "the daemon does not serve `{verb}` as this blit asks for it: it speaks another \
             contract version than this one (v{CONTRACT_VERSION}); both must be the same blit \
             release"
        );
    }
    eyre::eyre!(status.message().to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// AC-11: the daemon answers an asker of its own contract and refuses
    /// one of any other, older or newer, naming both versions; and an
    /// asker told "unimplemented" — a daemon too old to know the request —
    /// reports the same thing, naming the verb.
    #[test]
    fn a_utility_request_is_answered_only_between_the_same_contract() {
        check(CONTRACT_VERSION).expect("the same contract");
        for other in [CONTRACT_VERSION - 1, CONTRACT_VERSION + 1, 0] {
            let status = check(other).expect_err("another contract");
            assert_eq!(status.code(), tonic::Code::FailedPrecondition);
            assert!(
                status
                    .message()
                    .contains(&format!("daemon v{CONTRACT_VERSION}"))
                    && status.message().contains(&format!("client v{other}")),
                "{}",
                status.message()
            );
            // The asker shows the daemon's own words.
            assert_eq!(refusal("du", status.clone()).to_string(), status.message());
        }
        let old_daemon = refusal("du", tonic::Status::unimplemented("unknown method Du"));
        let said = old_daemon.to_string();
        assert!(
            said.contains("`du`") && said.contains("another contract version"),
            "{said}"
        );
        assert!(said.contains(&format!("v{CONTRACT_VERSION}")), "{said}");
        // Any other status is the daemon's message, unchanged.
        assert_eq!(
            refusal("df", tonic::Status::not_found("no such module")).to_string(),
            "no such module"
        );
    }
}

