   136	/// `start_name` (the last name of the path as it was typed). `emit` gets
   137	/// each entry found and each failure as the walk meets it; returning
   138	/// `Err(Stopped)` ends the walk.
   139	pub fn find(
   140	    start: &Path,
   141	    start_name: &[u8],
   142	    options: &FindOptions,
   143	    emit: &mut dyn FnMut(FindEvent) -> Result<(), Stopped>,
   144	) -> Result<(), FindEnd> {
   145	    let mut metadata = look_up(start, false).map_err(FindEnd::Start)?;
   146	    if options.follow_start && metadata.file_type().is_symlink() {
   147	        metadata = look_up(start, true).map_err(FindEnd::Start)?;
   148	    }
   149	    let kind = Kind::of(metadata.file_type());
   150	    if options.holds(start_name, kind) {
   151	        emit(FindEvent::Found(PathBuf::new())).map_err(FindEnd::Stopped)?;
   152	    }
   153	    if kind != Some(Kind::Directory) || options.max_depth == Some(0) {
   154	        return Ok(());
   155	    }
   156	
   157	    /// One directory being read.
   158	    struct Frame {
   159	        relative_path: PathBuf,
   160	        entries: fs::ReadDir,
   161	    }
   162	    let mut frames: Vec<Frame> = Vec::new();
   163	    match fs::read_dir(start) {
   164	        Ok(entries) => frames.push(Frame {
   165	            relative_path: PathBuf::new(),
   166	            entries,
   167	        }),
   168	        Err(error) => {
   169	            return emit(FindEvent::Failure(FindFailure {
   170	                relative_path: PathBuf::new(),
   171	                error,
   172	            }))
   173	            .map_err(FindEnd::Stopped);
   174	        }
   175	    }
   176	    while let Some(frame) = frames.last_mut() {
   177	        let Some(entry) = frame.entries.next() else {
   178	            frames.pop();
   179	            continue;
   180	        };
   181	        let entry = match entry {
   182	            Ok(entry) => entry,
   183	            Err(error) => {
   184	                let relative_path = frame.relative_path.clone();
   185	                emit(FindEvent::Failure(FindFailure {
   186	                    relative_path,
   187	                    error,
   188	                }))
   189	                .map_err(FindEnd::Stopped)?;
   190	                continue;
   191	            }
   192	        };
   193	        let name = entry.file_name();
   194	        let relative_path = frame.relative_path.join(&name);
   195	        // The listing's own word for the entry: no lookup, and never
   196	        // through a link.
   197	        let kind = match entry.file_type() {
   198	            Ok(kind) => Kind::of(kind),
   199	            Err(error) => {
   200	                emit(FindEvent::Failure(FindFailure {
   201	                    relative_path,
   202	                    error,
   203	                }))
   204	                .map_err(FindEnd::Stopped)?;
   205	                continue;
   206	            }
   207	        };
   208	        if options.holds(&name_bytes(&name), kind) {
   209	            emit(FindEvent::Found(relative_path.clone())).map_err(FindEnd::Stopped)?;
   210	        }
   211	        // This entry is `frames.len()` levels below the start.
   212	        let enter = kind == Some(Kind::Directory)
   213	            && options
   214	                .max_depth
   215	                .is_none_or(|max| (frames.len() as u32) < max);
   216	        if !enter {
   217	            continue;
   218	        }
   219	        match fs::read_dir(entry.path()) {
   220	            Ok(entries) => frames.push(Frame {
   221	                relative_path,
   222	                entries,
   223	            }),
   224	            Err(error) => {
   225	                emit(FindEvent::Failure(FindFailure {
   226	                    relative_path,
   227	                    error,
   228	                }))
   229	                .map_err(FindEnd::Stopped)?;
   230	            }
   231	        }
   232	    }
   233	    Ok(())
   234	}
