     2	//! (`docs/plan/UTILITY_VERBS_LOCAL_PARITY.md` slice 3, AC-4).
     3	//!
     4	//! `-name PATTERN` and `-iname PATTERN` compare an entry's BASE NAME with
     5	//! a shell pattern: `*` is any run of characters (a leading dot
     6	//! included), `?` is any one, `[...]` is one of a set, and `\` takes the
     7	//! next character as itself. The reference is GNU find 4.11 under
     8	//! `C.UTF-8`, and two of its rules are not what the transfer filters do —
     9	//! each verb answers to the tool it is named after:
    10	//!
    11	//! - **Two readings.** A name matches when the pattern fits it read as
    12	//!   CHARACTERS or read as BYTES. So `?.dat` finds `é.dat` (one
    13	//!   character) and `??.dat` finds it too (two bytes). A name or a pattern
    14	//!   that is not valid UTF-8 has only the byte reading.
    15	//! - **`-iname` compares one character at a time by its lowercase form**
    16	//!   — not by case folding. `σ.sig` finds `Σ.sig` and not `ς.sig`, whose
    17	//!   lowercase is itself; `i.x` finds `İ.x` and not `ı.x`.
    18	//!
    19	//! This is not [`crate::fs_enum`]'s glob engine and shares nothing with
    20	//! it: a transfer's `--exclude` follows rsync's rule
    21	//! (`docs/plan/EXCLUDE_CASE_MATCHING.md`), `find` follows find's.
    22	
    23	/// A `-name` or `-iname` pattern, ready to be matched against base names.
    24	#[derive(Debug, Clone)]
    25	pub struct NamePattern {
    26	    as_bytes: Vec<Token<u8>>,
    27	    /// The pattern read as characters; `None` when it is not valid UTF-8.
    28	    as_chars: Option<Vec<Token<char>>>,
    29	    ignore_case: bool,
    30	}
    31	
    32	impl NamePattern {
    33	    /// `pattern` as typed; `ignore_case` for `-iname`. An error names what
    34	    /// in the pattern this matcher does not read — never silently another
    35	    /// meaning.
    36	    pub fn new(pattern: &[u8], ignore_case: bool) -> Result<Self, String> {
    37	        let as_chars = match std::str::from_utf8(pattern) {
    38	            Ok(text) => Some(compile(&text.chars().collect::<Vec<char>>())?),
    39	            Err(_) => None,
    40	        };
    41	        Ok(Self {
    42	            as_bytes: compile(pattern)?,
    43	            as_chars,
    44	            ignore_case,
    45	        })
    46	    }
    47	
    48	    /// Whether the pattern fits `name` — one base name, as its bytes.
    49	    pub fn matches(&self, name: &[u8]) -> bool {
    50	        if let (Some(tokens), Ok(text)) = (&self.as_chars, std::str::from_utf8(name)) {
    51	            let chars: Vec<char> = text.chars().collect();
    52	            if fits(tokens, &chars, self.ignore_case) {
    53	                return true;
    54	            }
    55	        }
    56	        fits(&self.as_bytes, name, self.ignore_case)
    57	    }
    58	}
