   182	fn compile<U: Unit>(pattern: &[U]) -> Result<Vec<Token<U>>, String> {
   183	    let mut tokens = Vec::new();
   184	    let mut at = 0;
   185	    while let Some(&unit) = pattern.get(at) {
   186	        at += 1;
   187	        let token = if is(unit, b'*') {
   188	            // A run of stars is one.
   189	            if tokens.last() == Some(&Token::Run) {
   190	                continue;
   191	            }
   192	            Token::Run
   193	        } else if is(unit, b'?') {
   194	            Token::One
   195	        } else if is(unit, b'\\') {
   196	            match pattern.get(at) {
   197	                Some(&escaped) => {
   198	                    at += 1;
   199	                    Token::Literal(escaped)
   200	                }
   201	                None => Token::Nothing,
   202	            }
   203	        } else if is(unit, b'[') {
   204	            match set(pattern, at)? {
   205	                Some((token, after)) => {
   206	                    at = after;
   207	                    token
   208	                }
   209	                // Never closed: a `[` like any other character.
   210	                None => Token::Literal(unit),
   211	            }
   212	        } else {
   213	            Token::Literal(unit)
   214	        };
   215	        tokens.push(token);
   216	    }
   217	    Ok(tokens)
   218	}
