   220	/// The bracket expression whose `[` stands just before `from`: the token
   221	/// and where the pattern goes on after its `]`; `None` when it is never
   222	/// closed.
   223	fn set<U: Unit>(pattern: &[U], from: usize) -> Result<Option<(Token<U>, usize)>, String> {
   224	    let mut at = from;
   225	    let negated = pattern
   226	        .get(at)
   227	        .is_some_and(|&unit| is(unit, b'!') || is(unit, b'^'));
   228	    if negated {
   229	        at += 1;
   230	    }
   231	    let mut members = Vec::new();
   232	    let first = at;
   233	    loop {
   234	        let Some(&unit) = pattern.get(at) else {
   235	            return Ok(None);
   236	        };
   237	        at += 1;
   238	        // A `]` closes the set, unless it stands first in it.
   239	        if is(unit, b']') && at - 1 != first {
   240	            return Ok(Some((Token::Set { negated, members }, at)));
   241	        }
   242	        let start = if is(unit, b'\\') {
   243	            let Some(&escaped) = pattern.get(at) else {
   244	                return Ok(None);
   245	            };
   246	            at += 1;
   247	            escaped
   248	        } else if is(unit, b'[') && pattern.get(at).is_some_and(|&next| is(next, b':')) {
   249	            // `[:name:]`, when it is closed; else `[` is a member.
   250	            let name: Vec<u8> = pattern[at + 1..]
   251	                .iter()
   252	                .map_while(|unit| unit.ascii().filter(u8::is_ascii_lowercase))
   253	                .collect();
   254	            let end = at + 1 + name.len();
   255	            let closed = pattern.get(end).is_some_and(|&c| is(c, b':'))
   256	                && pattern.get(end + 1).is_some_and(|&c| is(c, b']'));
   257	            if closed {
   258	                let class = Class::named(&name).ok_or_else(|| {
   259	                    format!(
   260	                        "[:{}:] is not a character class",
   261	                        String::from_utf8_lossy(&name)
   262	                    )
   263	                })?;
   264	                members.push(Member::Class(class));
   265	                at = end + 2;
   266	                continue;
   267	            }
   268	            unit
   269	        } else if is(unit, b'[')
   270	            && pattern
   271	                .get(at)
   272	                .is_some_and(|&next| is(next, b'=') || is(next, b'.'))
   273	        {
   274	            return Err(
   275	                "an equivalence class ([=a=]) or collating symbol ([.a.]) in a bracket \
   276	                 expression is not supported"
   277	                    .to_string(),
   278	            );
   279	        } else {
   280	            unit
   281	        };
   282	        // `a-c`, when something other than the closing `]` follows the `-`.
   283	        let ranged = pattern.get(at).is_some_and(|&dash| is(dash, b'-'))
   284	            && pattern.get(at + 1).is_some_and(|&end| !is(end, b']'));
   285	        if !ranged {
   286	            members.push(Member::One(start));
   287	            continue;
   288	        }
   289	        let mut end = pattern[at + 1];
   290	        at += 2;
   291	        if is(end, b'\\') {
   292	            let Some(&escaped) = pattern.get(at) else {
   293	                return Ok(None);
   294	            };
   295	            at += 1;
   296	            end = escaped;
   297	        }
   298	        members.push(Member::Range(start, end));
   299	    }
   300	}
