   302	impl<U: Unit> Token<U> {
   303	    /// Whether this token takes `unit` as the one character it stands for.
   304	    fn takes(&self, unit: U, ignore_case: bool) -> bool {
   305	        let fold = |unit: U| if ignore_case { unit.lower() } else { unit };
   306	        match self {
   307	            Token::One => true,
   308	            Token::Literal(literal) => fold(*literal) == fold(unit),
   309	            Token::Set { negated, members } => {
   310	                let folded = fold(unit);
   311	                let held = members.iter().any(|member| match member {
   312	                    Member::One(one) => fold(*one) == folded,
   313	                    Member::Range(low, high) => fold(*low) <= folded && folded <= fold(*high),
   314	                    // A class is asked about the character as it is
   315	                    // written, in either mode — as the reference asks.
   316	                    Member::Class(class) => unit.is(*class),
   317	                });
   318	                held != *negated
   319	            }
   320	            Token::Run | Token::Nothing => false,
   321	        }
   322	    }
   323	}
   324	
   325	fn fits<U: Unit>(tokens: &[Token<U>], name: &[U], ignore_case: bool) -> bool {
   326	    let (mut token, mut unit) = (0, 0);
   327	    // Where to go back to: the token after the last `*`, and how much of
   328	    // the name that star has taken so far.
   329	    let mut star: Option<(usize, usize)> = None;
   330	    loop {
   331	        match tokens.get(token) {
   332	            Some(Token::Run) => {
   333	                star = Some((token + 1, unit));
   334	                token += 1;
   335	                continue;
   336	            }
   337	            Some(Token::Nothing) => return false,
   338	            Some(one) if unit < name.len() && one.takes(name[unit], ignore_case) => {
   339	                token += 1;
   340	                unit += 1;
   341	                continue;
   342	            }
   343	            None if unit == name.len() => return true,
   344	            _ => {}
   345	        }
   346	        match star {
   347	            Some((after, taken)) if taken < name.len() => {
   348	                star = Some((after, taken + 1));
   349	                token = after;
   350	                unit = taken + 1;
   351	            }
   352	            _ => return false,
   353	        }
   354	    }
   355	}
