   303	    /// Whether this token takes `unit` as the one character it stands for.
   304	    fn takes(&self, unit: U, ignore_case: bool) -> bool {
   305	        let fold = |unit: U| if ignore_case { unit.lower() } else { unit };
   306	        match self {
   307	            Token::One => true,
   308	            Token::Literal(literal) => fold(*literal) == fold(unit),
   309	            Token::Set { negated, members } => {
   310	                let folded = fold(unit);
